import { useState } from "react";

export default function Game() {
  // HISTORY now stores BOTH:
  // - board state (squares)
  // - identity (move number)
  const [history, setHistory] = useState([
    { squares: Array(9).fill(null), move: 0 },
  ]);

  // Pointer to which move we're viewing
  // This is ALWAYS an index into history (NOT a move ID)
  const [currentMove, setCurrentMove] = useState(0);

  // UI toggle only (does NOT affect data)
  const [isReversed, setIsReversed] = useState(false);

  // Derived current board from state pointer
  const currentSquares = history[currentMove].squares;

  // Derived game state
  const xIsNext = currentMove % 2 === 0;

  // ----------------------------------------------------
  // HANDLE PLAY (updates HISTORY, not UI rendering)
  // ----------------------------------------------------
  function handlePlay(nextSquares) {
    const nextHistory = [
      // keep only history up to current move (time travel behavior)
      ...history.slice(0, currentMove + 1),

      // NEW MOVE ENTRY has explicit identity
      {
        squares: nextSquares,
        move: currentMove + 1,
      },
    ];

    setHistory(nextHistory);

    // IMPORTANT:
    // currentMove is just a pointer → last element index
    setCurrentMove(nextHistory.length - 1);
  }

  // Jump uses INDEX in history (not entry.move)
  function jumpTo(nextMove) {
    setCurrentMove(nextMove);
  }

  // ----------------------------------------------------
  // VIEW LOGIC ONLY (NO DATA MODIFICATION)
  // ----------------------------------------------------

  // NEVER mutate history — create a display version instead
  const orderedHistory = isReversed ? [...history].reverse() : history;

  // ----------------------------------------------------
  // MOVES LIST
  // ----------------------------------------------------

  const moves = orderedHistory.map((entry) => {
    // entry = { squares, move }

    const isCurrent = entry === history[currentMove];

    // Build description based on REAL move identity
    let description;

    if (isCurrent) {
      description = `You are at move #${entry.move}`;
    } else if (entry.move > 0) {
      description = `Go to move #${entry.move}`;
    } else {
      description = "Go to game start";
    }

    return (
      <li key={entry.move}>
        {/* 
          IMPORTANT:
          We always use entry.move for jumping,
          NOT map index (which changes when reversed)
        */}
        {isCurrent ? (
          <p>{description}</p>
        ) : (
          <button onClick={() => jumpTo(entry.move)}>{description}</button>
        )}
      </li>
    );
  });

  // Toggle is PURE UI state
  function flipMoveOrder() {
    setIsReversed((prev) => !prev);
  }

  return (
    <>
      <div className="game-board">
        <Board xIsNext={xIsNext} squares={currentSquares} onPlay={handlePlay} />
      </div>

      <div className="flip-move-order">
        <button onClick={flipMoveOrder}>Flip Move Order</button>
      </div>

      <div className="game-info">
        <ol>{moves}</ol>
      </div>
    </>
  );
}
